'use strict';
(()=>{
const {words,meta}=window.KOTOBA_DATA,E=window.KotobaEngine,Q=window.KotobaQuiz,$=s=>document.querySelector(s),byId=new Map(words.map(w=>[w.id,w]));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const priorityLabel={A:'A · 优先掌握',B:'B · 重点巩固',C:'C · 阅读识记'},viewNames={today:'今日学习',review:'间隔复习',library:'全部词库',mistakes:'易错与收藏',stats:'学习记录',about:'词库与筛选依据'};
let state=E.fresh(),storageOK=true,loadError=false,migrated=false;
try{const current=localStorage.getItem(E.KEY),legacy=!current&&localStorage.getItem(E.LEGACY_KEY),raw=current||legacy;migrated=!!legacy;if(raw){try{state=E.validate(JSON.parse(raw),new Set(byId.keys()));}catch(e){loadError=true;}}}catch(e){storageOK=false;}
let view='today',tab='card',session=null,revealed=false,kanaVisible=false,quiz=null,query='',priority='all',lesson='all',listPage=0,mistakeFilter='all',pendingImport=null,toastTimer,previousQuizId=null;
const lessons=Array.from(new Set(words.map(w=>w.lesson?.split('-')[0]).filter(Boolean))).sort((a,b)=>a-b);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function save(){state.savedAt=new Date().toISOString();try{localStorage.setItem(E.KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('浏览器未能保存进度，请先导出备份。');}updateSaveLabel();}
function updateSaveLabel(){$('#saveStatus').textContent=storageOK?'● 本机保存':'○ 未能保存';$('#saveStatus').style.color=storageOK?'':'#c48776';}
function src(w){const label=w.collection==='additional'?'新增词表':'原词表';return w.source==='book'?`${label} 第${w.page}页 · ${w.lesson?'第'+w.lesson+'课':'课次待补'}`:'参照补充词';}
function displayWord(w){return (w.quizWritten||w.word).replace(/（.*?）/g,'');}
function fmtDate(d){return new Date(d).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric'});}
function goto(v){if(!viewNames[v])v='today';view=v;listPage=0;document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===v));document.title='拾词 · '+viewNames[v];if(location.hash!=='#'+v)history.replaceState(null,'','#'+v);render();}
function weekDays(){const now=Date.now(),arr=[];for(let i=6;i>=0;i--){const t=now-i*E.DAY,d=E.today(t);arr.push({day:d,label:['日','一','二','三','四','五','六'][new Date(d+'T00:00:00+08:00').getDay()],count:state.logs.filter(l=>l.day===d).length,isToday:i===0});}return arr;}
function progressPanel(){const c=E.counts(state),passed=words.filter(w=>state.words[w.id]?.seen>0&&state.words[w.id].readingStreak>=5).length;return `<aside class="right-rail"><section class="panel"><h3>学习计划</h3><div class="goal-row"><span>今日新学</span><b>${c.newToday} / ${state.settings.newGoal}</b></div><div class="goal-row"><span>今日复习</span><b>${c.reviewToday} / ${state.settings.reviewGoal}</b></div><div class="goal-row"><span>到期复习</span><b>${c.due}</b></div><div class="mini-line"></div><div class="goal-row"><span>累计已学</span><b>${c.learned}</b></div><div class="goal-row"><span>读音已过关</span><b>${passed}</b></div><button class="text-button" data-action="settings">调整计划与备份</button></section><section class="panel"><h3>训练规则</h3><p class="small muted">从所有已背词中随机抽题。看汉字选假名、看假名选汉字随机出现。</p><p class="small muted">每词连对5次后退出训练；错一次，该词重新从0计数。</p></section></aside>`;}
function bookOverview(){return '';}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'numeric',hourCycle:'h23'}).format(new Date()));return h<11?'早上好':h<14?'中午好':h<18?'下午好':'晚上好';}
function welcome(title,sub){return `<section class="welcome"><div><h1>${title}</h1><p>${sub}</p></div></section>`;}
function getSession(mode='mixed'){if(!session||session.mode!==mode){session={mode,queue:E.queue(words,state,mode).map(w=>w.id),index:0,done:0,startSize:0,retries:{}};session.startSize=session.queue.length;revealed=false;quiz=null;}return session;}
function current(mode){const s=getSession(mode);return byId.get(s.queue[s.index]);}
function emptyCard(mode){const c=E.counts(state),selected=E.filter(words,state.settings),unseen=selected.filter(w=>!state.words[w.id]?.seen).length;const isReview=mode==='review';let title=isReview?'到期的词，都复习好了':'这一组，已经记进去了';let copy=isReview?'还没学过单词时，先去「今日学习」开启第一组。':`今天已新学 ${c.newToday} 词、复习 ${c.reviewToday} 词。可以休息一下，也可以自由练习。`;if(isReview&&c.due>0){title='今天的复习计划已完成';copy=`仍有 ${c.due} 词到期，可以继续复习，或调整范围与每日上限。`;}if(!selected.length){title='当前范围里没有单词';copy='请切换优先级或课次后再开始。';}return `<div class="empty"><div class="empty-glyph">好</div><h2>${title}</h2><p>${copy}</p><div class="button-row">${isReview&&c.due?'<button class="button primary" data-action="extraReview">再复习10个</button>':''}${!isReview&&unseen?'<button class="button primary" data-action="extra">再学10个新词</button>':''}<button class="button ${isReview?'primary':'secondary'}" data-action="${isReview?'goToday':'quiz'}">${isReview?'去学新词':'自由读音训练'}</button></div></div>`;}
function phraseHTML(w,limit=3){if(!w.phrases?.length)return '';return `<section class="linked-phrases"><div class="detail-label">联合记忆</div>${w.phrases.slice(0,limit).map(p=>`<div class="linked-phrase"><div class="phrase-jp" lang="ja">${esc(p.jp)}</div><div class="phrase-reading" lang="ja">${esc(p.kana)}</div><div class="phrase-meaning">${esc(p.meaning)}</div><div class="phrase-links">${p.words.map(x=>`<button class="phrase-word" data-action="detail" data-id="${x.id}" title="${esc(x.kana+' · '+x.meaning)}">${esc(x.word)}</button>`).join('<span>＋</span>')}</div></div>`).join('')}</section>`;}
function wordFormsHTML(w){const f=w.forms,base=f&&w.pos.includes('サ变')?displayWord(w)+'する':displayWord(w);if(!f)return `<div class="inline-word-type"><span class="detail-label">词形</span><span lang="ja">${esc(base)}</span><span>${esc(w.pos)}</span></div>`;const forms=[['基本形',base],...Object.entries({masu:'ます形',te:'て形',ta:'た形',nai:'ない形',potential:'可能形'}).filter(([key])=>f[key]).map(([key,label])=>[label,f[key]])];return `<section class="inline-forms" aria-label="词形与变形"><div class="detail-label">词形与变形 <span class="form-pos">${esc(w.pos)}</span></div><div class="conjugation">${forms.map(([label,value])=>`<div class="form-cell"><small>${label}</small><span lang="ja">${esc(value)}</span></div>`).join('')}</div><p class="form-caption">各形从基本形变化；サ变名词按「名词＋する」活用。</p></section>`;}
function completeSourcesHTML(w){const rows=(w.sources||[]).filter(x=>x.collection!=='exam').map(x=>`${x.collection==='additional'?'新增词表':'原词表'} 第${x.page}页 · ${x.lesson?'第'+x.lesson+'课':'课次待补'}`);return `<section class="card-provenance" aria-label="完整来源"><div class="source-list"><span class="detail-label">完整来源</span><span>${rows.length?rows.map(esc).join('；'):esc(src(w))}</span></div><div class="evidence">${esc(w.reason)}${w.examReference?'<br>'+esc(w.examReference):''}</div></section>`;}
function dictionaryHTML(w){return `<a class="text-button dictionary-link" href="https://www.weblio.jp/content/${encodeURIComponent(displayWord(w))}" target="_blank" rel="noopener noreferrer">外部词典核对 ↗</a>`;}
function wordCard(w,s){const a=state.words[w.id],star=!!a?.star;return `<article class="study-card${revealed?' is-revealed':''}"><div class="progress-line"><div style="width:${s.queue.length?Math.min(100,s.index/s.queue.length*100):0}%"></div></div><div class="card-meta"><div><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span><span class="source">${src(w)}</span></div><div class="card-actions"><button class="icon-button ${star?'starred':''}" data-action="star" data-id="${w.id}" aria-label="${star?'取消收藏':'收藏单词'}">${star?'★':'☆'}</button><button class="icon-button" data-action="speak" data-id="${w.id}" aria-label="朗读单词">◖))</button></div></div><div class="word-core"><h2 lang="ja">${esc(displayWord(w))}</h2><div class="kana" lang="ja">${revealed||kanaVisible?esc(w.kana):'&nbsp;'}</div>${revealed?`<div class="word-meaning">${esc(w.meaning)}</div><span class="pos">${esc(w.pos)}</span>`:'<div class="recall-hint">先回想它的读音和意思</div>'}</div>${revealed?`<div class="card-detail"><div class="detail-label">搭配与易错提醒</div><p>${esc(w.note)}</p>${w.example?`<div class="example"><div class="jp" lang="ja">${esc(w.example.jp)}</div><div class="zh">${esc(w.example.zh)}</div></div>`:''}${wordFormsHTML(w)}${phraseHTML(w)}${completeSourcesHTML(w)}${dictionaryHTML(w)}</div>`:''}<div class="card-bottom">本组 ${Math.min(s.index+1,s.queue.length)} / ${s.queue.length}</div></article>`;}
function controls(w){return `<div class="study-controls">${!revealed?'<button class="button primary full" data-action="reveal">查看读音与释义 <kbd>空格</kbd></button>':`<div class="grade-grid"><button class="grade again" data-action="rate" data-grade="again">1 · 再学一次<small>本组重现 · 10分钟后复习</small></button><button class="grade" data-action="rate" data-grade="hard">2 · 还不太熟<small>1天后再见</small></button><button class="grade good" data-action="rate" data-grade="good">3 · 认识了<small>${state.words[w.id]?.seen?E.INTERVALS[state.words[w.id].lastReviewDay===E.today()?state.words[w.id].stage:Math.min(5,state.words[w.id].stage+1)]:1}天后再见</small></button></div>`}</div><div class="shortcut-guide"><kbd>空格</kbd> 揭晓 <span> &nbsp; </span><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd> 标记熟悉度 <span> &nbsp; </span><kbd>P</kbd> 发音</div>`;}
function studyHTML(mode='mixed'){const s=getSession(mode),w=current(mode);return `<div class="study-layout"><section class="study-stage"><div class="section-bar study-toolbar"><div><h1 class="study-title">${mode==='review'?'到期复习':'今日单词'}</h1><p class="study-instruction">${mode==='review'?'复习已经到期的词。':'按优先级学习，先回忆，再查看答案。'}</p></div><div class="switches"><button data-action="card" class="${tab==='card'?'active':''}">单词卡</button><button data-action="quiz" class="${tab==='quiz'?'active':''}">读音训练</button></div></div>${tab==='quiz'?quizHTML():w?wordCard(w,s)+controls(w):emptyCard(mode)}<div class="session-banner"><span>${words.length} 项精选 · 已学 ${E.counts(state).learned} 项</span><button class="text-button" data-action="range">选择学习范围</button></div>${bookOverview()}</section>${progressPanel()}</div>`;}
function makeQuiz(){quiz=Q.createQuestion(words,state,previousQuizId);if(quiz)previousQuizId=quiz.id;}
function quizHTML(){
 if(!quiz)makeQuiz();
 const learned=E.counts(state).learned,remaining=E.readingPool(words,state).length,passed=learned-remaining;
 if(!quiz)return `<div class="empty"><h2>${learned?'已学词已全部过关':'先学词，再训练'}</h2><p>${learned?`已背的 ${learned} 个词都已连续答对5次。学新词后，会自动加入训练。`:'在单词卡中学过的词会自动进入训练。训练不受每日新词量、课次和优先级筛选限制。'}</p><button class="button primary" data-action="card">去学单词</button></div>`;
 const w=byId.get(quiz.id),answered=quiz.selected!==null,streak=state.words[w.id]?.readingStreak||0,correct=answered&&quiz.selected===quiz.answer;
 return `<div class="training-summary"><span>所有已背词 · 待练 ${remaining} · 已过关 ${passed}</span><span>${quiz.type==='kana'?'选假名':'选日语汉字'}</span></div><article class="study-card quiz-card${answered?' is-answered':''}"><div class="card-meta"><span class="small muted">${quiz.type==='kana'?'选择正确读音':'选择符合词义的日语写法'}</span><span class="streak-counter">连对 ${streak} / 5</span></div><div class="word-core"><h2 lang="ja" class="${quiz.type==='kanji'?'kana-prompt':''}">${esc(quiz.prompt)}</h2><div class="quiz-hint">${esc(quiz.hint)}</div></div><div class="quiz-options">${quiz.options.map((a,i)=>`<button class="quiz-choice ${answered&&a===quiz.answer?'right':''} ${answered&&quiz.selected===a&&a!==quiz.answer?'wrong':''}" ${answered?'disabled':''} data-action="quizAnswer" data-answer="${esc(a)}">${i+1}. ${esc(a)}</button>`).join('')}</div>${answered?`<div class="quiz-feedback"><strong>${correct?(streak>=5?'连续答对5次，已退出训练。':`答对了 · 当前连对${streak}次`):'本词计数已归零，从0重新开始。'}</strong><p><span lang="ja">${esc(displayWord(w))} · ${esc(w.kana)}</span><br>${esc(w.meaning)}<br>${esc(w.note)}</p>${phraseHTML(w,2)}<button class="text-button" data-action="speak" data-id="${w.id}">听正确读音</button></div>`:''}</article>${answered?'<button class="button primary full" style="margin-top:16px" data-action="nextQuiz">下一题 <kbd>回车</kbd></button>':''}<div class="shortcut-guide"><kbd>1</kbd>—<kbd>4</kbd> 选择答案　<kbd>回车</kbd> 下一题</div>`;
}
function filteredList(){return words.filter(w=>{const a=state.words[w.id];return (priority==='all'||w.priority===priority)&&(lesson==='all'||(lesson==='exam'?w.source==='exam':w.lesson?.split('-')[0]===lesson))&&(!query||[w.word,w.quizWritten||'',...(w.aliases||[]),w.kana,w.meaning,w.pos,w.note].some(t=>t.includes(query)))&&(view!=='mistakes'||(mistakeFilter==='star'?a?.star:mistakeFilter==='wrong'?a?.lapses>0:a?.star||a?.lapses>0));});}
function filtersHTML(){return `<div class="filters"><input class="search" id="wordSearch" type="search" placeholder="查找日语、假名或中文释义…" value="${esc(query)}" aria-label="搜索词库"><select id="priorityFilter" aria-label="优先级">${[['all','全部优先级'],['A','A · 优先掌握'],['B','B · 重点巩固'],['C','C · 阅读识记']].map(([v,l])=>`<option value="${v}" ${priority===v?'selected':''}>${l}</option>`).join('')}</select><select id="lessonFilter" aria-label="教材课次"><option value="all">全部课次</option>${lessons.map(l=>`<option value="${l}" ${lesson===l?'selected':''}>第${l}课</option>`).join('')}<option value="exam" ${lesson==='exam'?'selected':''}>回忆卷补充</option></select>${view==='mistakes'?`<select id="mistakeFilter" aria-label="易错或收藏">${[['all','易错与收藏'],['wrong','只看易错'],['star','只看收藏']].map(([v,l])=>`<option value="${v}" ${mistakeFilter===v?'selected':''}>${l}</option>`).join('')}</select>`:''}</div>`;}
function tableHTML(){const list=filteredList(),size=25,max=Math.max(1,Math.ceil(list.length/size));listPage=Math.min(listPage,max-1);const slice=list.slice(listPage*size,(listPage+1)*size);return `<div class="section-bar"><span class="list-count">找到 ${list.length} 项 · 点击单词查看读音、用法与词形</span><button class="text-button" data-action="csv">↓ 导出完整词库</button></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>单词 / 假名</th><th>中文释义</th><th>优先级</th><th>来源</th><th>学习状态</th><th>收藏</th></tr></thead><tbody>${slice.map(w=>{const a=state.words[w.id];return `<tr data-id="${w.id}" tabindex="0" role="button" aria-label="查看${esc(w.word)}"><td><strong lang="ja">${esc(w.quizWritten||w.word)}</strong><span class="reading" lang="ja">${esc(w.kana)}</span></td><td>${esc(w.meaning)}<span class="reading">${esc(w.pos)}</span></td><td><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span></td><td><span class="small">${src(w)}</span></td><td><span class="small">${!a?.seen?'未学习':a.stage>=3?'较熟悉':a.due<=Date.now()?'待复习':'已学习'}${a?.lapses?` · 易错${a.lapses}次`:''}</span></td><td><button class="icon-button ${a?.star?'starred':''}" data-action="star" data-id="${w.id}" aria-label="${a?.star?'取消收藏':'收藏'}${esc(w.word)}">${a?.star?'★':'☆'}</button></td></tr>`}).join('')}</tbody></table></div><div class="pagination"><span>第 ${listPage+1} / ${max} 页</span><div class="button-row"><button class="button secondary" data-action="prevPage" ${listPage===0?'disabled':''}>← 上一页</button><button class="button secondary" data-action="nextPage" ${listPage>=max-1?'disabled':''}>下一页 →</button></div></div>`:'<div class="empty"><h2>这里还没有单词</h2><p>试试更换搜索条件。学习中点「再学一次」，或收藏的词，会出现在这里。</p></div>'}`;}
function libraryHTML(){const isMistake=view==='mistakes';return `${welcome(isMistake?'易错与收藏':'全部词库',isMistake?'把易忘的、易混的、想留下的，放在这里慢慢熟悉。':`${words.length} 项 · 原词表与新增词表已合并去重`)}${filtersHTML()}<div id="wordTable">${tableHTML()}</div>`;}
function statsHTML(){const c=E.counts(state),days=weekDays(),max=Math.max(1,...days.map(d=>d.count));return `${welcome('学习记录','只记录真实学习，不预填打卡。复习间隔会随你的熟悉度变化。')}<div class="stat-grid">${[[c.learned,'累计学过的词'],[c.mastered,'较熟悉 · 至少14天间隔'],[c.due,'当前到期复习'],[new Set(state.logs.map(l=>l.day)).size,'有练习记录的天数']].map(([n,t])=>`<section class="panel"><strong>${n}</strong><span>${t}</span></section>`).join('')}</div><div class="about-grid"><section class="panel"><h3>近七天练习次数</h3><div class="chart-bars">${days.map(d=>`<div class="bar"><strong>${d.count}</strong><div style="height:${d.count/max*110}px" title="${d.day} · ${d.count}次"></div><span>${d.day.slice(5)}</span></div>`).join('')}</div><p class="muted small">每次标记或答题算一次练习，同一个词可能出现多次。</p></section><section class="panel"><h3>词库熟悉度</h3>${['A','B','C'].map(p=>{const total=words.filter(w=>w.priority===p).length,n=words.filter(w=>w.priority===p&&state.words[w.id]?.seen>0).length;return `<div class="goal-row"><span>${priorityLabel[p]}</span><b>${n} / ${total}</b></div><div class="progress-line"><div style="width:${n/total*100}%"></div></div>`}).join('')}<p class="muted small" style="margin-top:24px">读音训练记录每词连对次数：达到5次后过关，答错则归零。单词卡的间隔复习照常安排。</p><button class="text-button" data-action="settings">导出学习进度 ↗</button></section></div><div class="info-box">记忆安排：认识后依次在1、3、7、14、30、60天复习；「还不太熟」回到较短间隔，1天后复习；「再学一次」10分钟后到期，并在本组稍后重现。学习日按北京时间计算。</div>`;}
function aboutHTML(){return `${welcome('词库说明','按基础程度、搭配和活用的迁移价值分级，参考卷只用于判断题型。')}<section class="panel"><h3>词库范围</h3><p class="muted">${words.length}项，包含原词表精选、新增12页词表和少量补充词。重复词合并出处；同音异义、同形异读分别保留。两组照片分别标为「原词表」「新增词表」，不混用页码。无法辨认的课次留空。</p><p class="muted">A优先掌握，B重点巩固，C阅读识记；不按单套卷的出现次数预测考试概率。释义取常用义，词卡保留搭配与活用。已整理${meta.phraseCount}组联合记忆短语，覆盖${meta.wordsWithPhrases}项词条。</p><h3>读音与字形训练</h3><p class="muted">只从已背过的词中随机抽题，不受课次和等级筛选影响。「看汉字选假名」与「看假名选汉字」随机混合；纯假名词以中文提示选假名。两种题型共同累计：每词连续答对5次后退出训练，错一次，该词归零。正确答案揭晓后保留用法和短语，单词卡复习进度不受影响。</p><p class="muted">假名干扰项围绕同一读音改动长音、促音、拗音或清浊音；汉字干扰项采用目标词的形近字。错误选项是用于辨析的干扰写法，不是新增词条；同形异读及可接受的异体写法会避开。汉字题提供词义，防止同音词多解。</p><h3>进度</h3><p class="muted">保存在当前浏览器，换设备可导入导出备份。旧版背词进度会保留；旧读音记录按连续答对、遇错归零的顺序迁移。朗读使用设备的日语合成语音。</p></section><details class="panel"><summary>参考卷疑误与核对来源</summary>${meta.corrections.map(x=>`<div class="correction"><b>第${x.q}题 · ${esc(x.issue)}</b><p>${esc(x.fix)}</p></div>`).join('')}${meta.sources.map(x=>`<p class="small muted">${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>`:esc(x.title)}：${esc(x.description)}</p>`).join('')}</details><button class="button secondary" data-action="csv">下载完整词表</button>`;}
function render(){const y=window.scrollY,studying=view==='today'||view==='review';$('#main').classList.toggle('study-mode',studying);$('#dueNav').textContent=E.counts(state).due;$('#main').innerHTML=view==='today'?studyHTML():view==='review'?studyHTML('review'):view==='library'||view==='mistakes'?libraryHTML():view==='stats'?statsHTML():aboutHTML();updateSaveLabel();window.scrollTo(0,studying?0:y);}
function detail(id){const w=byId.get(id);if(!w)return;const f=w.forms;$('#detailContent').innerHTML=`<div class="detail-word" lang="ja">${esc(displayWord(w))}</div><div class="detail-reading" lang="ja">${esc(w.kana)}</div><div class="detail-meaning">${esc(w.meaning)}</div><div style="text-align:center"><span class="tag ${w.priority}">${priorityLabel[w.priority]}</span> <span class="pos">${esc(w.pos)}</span></div><div class="note-block">${esc(w.note)}</div>${f?`<div class="conjugation">${Object.entries({masu:'ます形',te:'て形',ta:'た形',nai:'ない形',potential:'可能形'}).filter(([k])=>f[k]).map(([k,l])=>`<div class="form-cell"><small>${l}</small><span lang="ja">${esc(f[k])}</span></div>`).join('')}</div><p class="muted small" style="margin-top:10px">变形从基本形直接生成；サ变名词显示「名词＋する」的形式。</p>`:''}${phraseHTML(w,12)}<div class="detail-footer">${(w.sources||[]).filter(x=>x.collection!=='exam').map(x=>`${x.collection==='additional'?'新增词表':'原词表'} 第${x.page}页 · ${x.lesson?'第'+x.lesson+'课':'课次待补'}`).join('<br>')||src(w)}<br>${esc(w.reason)}${w.examReference?'<br>'+esc(w.examReference):''}</div><div class="button-row"><button class="button primary" data-action="speak" data-id="${w.id}">朗读单词</button><a class="button secondary" href="https://www.weblio.jp/content/${encodeURIComponent(displayWord(w))}" target="_blank" rel="noopener noreferrer">外部词典核对 ↗</a></div>`;if(!$('#detailDialog').open)$('#detailDialog').showModal();}
function star(id){let a=state.words[id];if(!a)state.words[id]=a={stage:0,due:0,seen:0,lapses:0,star:false,learnedOn:E.today()};a.star=!a.star;save();render();toast(a.star?'已收藏，下次在「易错与收藏」见。':'已取消收藏。');}
function speak(id){const w=byId.get(id);if(!w)return;if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读，请使用 Safari、Chrome 或 Edge。');return;}const synth=window.speechSynthesis;const voice=synth.getVoices().find(v=>v.lang.startsWith('ja'));if(!voice){toast('设备暂未提供日语语音，请在系统语音设置中添加日语。');return;}synth.cancel();const u=new SpeechSynthesisUtterance(w.kana);u.lang='ja-JP';u.voice=voice;u.rate=.82;u.onerror=()=>toast('朗读未能播放，请检查系统日语语音。');synth.speak(u);}
function settings(){ $('#newGoal').value=state.settings.newGoal;$('#reviewGoal').value=state.settings.reviewGoal;$('#backupInfo').textContent=state.savedAt?'上次保存：'+new Date(state.savedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'还没有学习记录。';$('#settingsDialog').showModal();}
function download(text,name,type){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportState(){download(JSON.stringify({...state,exportedAt:new Date().toISOString(),dataVersion:meta.version},null,2),'shici-progress-'+E.today()+'.json','application/json');}
function csv(){const rows=[['单词','假名','中文','词性','优先级','教材课次','教材页码','来源','参考题号','用法提醒','联合记忆短语'],...words.map(w=>[w.quizWritten||w.word,w.kana,w.meaning,w.pos,w.priority,w.lesson||'',w.page||'',w.source==='book'?(w.collection==='additional'?'新增词表':'原词表'):'参照补充词',w.questions.join('、'),w.note,(w.phrases||[]).map(p=>p.jp+'（'+p.meaning+'）').join('；')])];download('\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'shici-vocabulary-'+E.today()+'.csv','text/csv;charset=utf-8');}
function range(){const old=$('#rangeDialog');if(old)old.remove();const d=document.createElement('dialog');d.id='rangeDialog';d.innerHTML=`<form method="dialog" class="dialog-head"><h2>选择学习范围</h2><button class="icon-button" aria-label="关闭">✕</button></form><div class="dialog-body"><p class="muted">新词会先按A、B、C顺序安排。切换范围不会删除已学进度。</p><div class="form-grid"><label>优先级<select id="studyPriority">${[['all','全部优先级'],['A','A · 优先掌握'],['B','B · 重点巩固'],['C','C · 阅读识记']].map(([v,l])=>`<option value="${v}" ${state.settings.priority===v?'selected':''}>${l}</option>`).join('')}</select></label><label>教材课次<select id="studyLesson"><option value="all">全部课次</option>${lessons.map(l=>`<option value="${l}" ${state.settings.lesson===l?'selected':''}>第${l}课</option>`).join('')}<option value="exam" ${state.settings.lesson==='exam'?'selected':''}>回忆卷补充</option></select></label></div><button class="button primary full" id="saveRange">开始这一范围</button></div>`;document.body.append(d);$('#saveRange').onclick=()=>{state.settings.priority=$('#studyPriority').value;state.settings.lesson=$('#studyLesson').value;save();session=null;quiz=null;d.close();render();toast('已切换学习范围。');};d.showModal();}
const actions={
 reveal(){revealed=true;render();},
 rate(el){const s=getSession(view==='review'?'review':'mixed'),w=current(s.mode);if(!revealed||!w)return;const grade=el.dataset.grade;E.rate(state,w.id,grade);if(grade==='again'&&(s.retries[w.id]||0)<2){s.queue.splice(Math.min(s.queue.length,s.index+4),0,w.id);s.retries[w.id]=(s.retries[w.id]||0)+1;}s.index++;s.done++;revealed=false;save();render();},
 star(el){star(el.dataset.id)},speak(el){speak(el.dataset.id)},detail(el){detail(el.dataset.id)},settings,range,csv,
 card(){tab='card';render()},quiz(){tab='quiz';render()},
 quizAnswer(el){if(!quiz||quiz.selected!==null)return;quiz.selected=el.dataset.answer;const correct=quiz.selected===quiz.answer;E.recordReading(state,quiz.id,correct,quiz.type);save();render();},
 nextQuiz(){quiz=null;render()},
 goToday(){tab='card';session=null;goto('today')},extra(){const arr=E.filter(words,state.settings).filter(w=>!state.words[w.id]?.seen).slice(0,10);session={mode:view==='review'?'review':'mixed',queue:arr.map(w=>w.id),index:0,done:0,startSize:arr.length,retries:{}};revealed=false;render();},
 extraReview(){const arr=E.filter(words,state.settings).filter(w=>state.words[w.id]?.seen>0&&state.words[w.id].due<=Date.now()).sort((a,b)=>state.words[a.id].due-state.words[b.id].due).slice(0,10);session={mode:'review',queue:arr.map(w=>w.id),index:0,done:0,startSize:arr.length,retries:{}};revealed=false;tab='card';render();},
 prevPage(){listPage--;$('#wordTable').innerHTML=tableHTML()},nextPage(){listPage++;$('#wordTable').innerHTML=tableHTML()}
};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button){if(button.disabled)return;const f=actions[button.dataset.action];if(f)f(button);return;}const nav=e.target.closest('[data-view]');if(nav){goto(nav.dataset.view);return;}const tr=e.target.closest('tr[data-id]');if(tr)detail(tr.dataset.id);});
document.addEventListener('input',e=>{if(e.target.id==='wordSearch'){query=e.target.value.trim();listPage=0;$('#wordTable').innerHTML=tableHTML();}});
document.addEventListener('change',e=>{if(['priorityFilter','lessonFilter','mistakeFilter'].includes(e.target.id)){if(e.target.id==='priorityFilter')priority=e.target.value;if(e.target.id==='lessonFilter')lesson=e.target.value;if(e.target.id==='mistakeFilter')mistakeFilter=e.target.value;listPage=0;$('#wordTable').innerHTML=tableHTML();}});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,select,textarea'))return;if(e.target.closest('tr[data-id]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();detail(e.target.closest('tr').dataset.id);return;}if(!['today','review'].includes(view))return;if(tab==='quiz'){if(quiz&&quiz.selected===null&&/^[1-4]$/.test(e.key)){e.preventDefault();actions.quizAnswer({dataset:{answer:quiz.options[Number(e.key)-1]}});}else if(e.key==='Enter'&&quiz?.selected!==null){e.preventDefault();actions.nextQuiz();}return;}const w=current(view==='review'?'review':'mixed');if(!w)return;if(e.code==='Space'){e.preventDefault();if(!revealed)actions.reveal();}else if(revealed&&/^[1-3]$/.test(e.key)){e.preventDefault();actions.rate({dataset:{grade:['again','hard','good'][Number(e.key)-1]}});}else if(e.key.toLowerCase()==='p'){e.preventDefault();speak(w.id);}});
$('#settingsButton').onclick=settings;
$('#helpButton').onclick=()=>toast('空格揭晓 · 1/2/3标记 · P朗读；读音训练用1—4选答案。');
$('#saveSettings').onclick=()=>{const a=Number($('#newGoal').value),b=Number($('#reviewGoal').value);if(!Number.isInteger(a)||a<1||a>100||!Number.isInteger(b)||b<1||b>200){toast('新词请输入1—100，复习请输入1—200之间的整数。');return;}state.settings.newGoal=a;state.settings.reviewGoal=b;save();session=null;$('#settingsDialog').close();render();toast('学习计划已保存。');};
$('#exportButton').onclick=exportState;$('#downloadWords').onclick=csv;
$('#importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>10000000)throw Error('备份文件过大，请选择小于10MB的JSON。');pendingImport=E.validate(JSON.parse(await f.text()),new Set(byId.keys()));const c=E.counts(pendingImport);$('#importSummary').textContent=`备份包含 ${c.learned} 个学过的词、${pendingImport.logs.length} 条练习记录。`;$('#settingsDialog').close();$('#importDialog').showModal();}catch(err){toast(err.message||'无法读取这个备份。');}};
$('#cancelImport').onclick=()=>{pendingImport=null;$('#importDialog').close();};$('#confirmImport').onclick=()=>{if(!pendingImport)return;exportState();state=pendingImport;pendingImport=null;session=null;quiz=null;save();$('#importDialog').close();render();toast('备份已导入，之前的进度也已下载备份。');};
if('speechSynthesis'in window)window.speechSynthesis.getVoices();
window.addEventListener('hashchange',()=>goto(location.hash.slice(1)));
window.addEventListener('storage',e=>{if(e.key===E.KEY&&e.newValue){try{state=E.validate(JSON.parse(e.newValue),new Set(byId.keys()));session=null;quiz=null;render();toast('已同步当前浏览器其他标签页的进度。');}catch(err){toast('其他标签页的进度无法载入，请导出备份。');}}});
window.addEventListener('pageshow',()=>{$('#dueNav').textContent=E.counts(state).due;});
goto(viewNames[location.hash.slice(1)]?location.hash.slice(1):'today');
if(migrated&&!loadError)save();
if(loadError)setTimeout(()=>toast('旧进度格式有异常，尚未覆盖。请先导出或检查原有备份。'),300);
})();
